    "hard_bit": "You can compute the coefficients, but it is not obvious why adding terms helps, or why the approximation collapses far from the centre.",
    "shows": "The polynomial is built up one term at a time against sin(x). Each new term grips the curve over a wider interval, and outside that interval it shoots off to infinity - which is what radius of convergence means, visually.",
    "source": "\"\"\"Taylor series visualisation (IB HL Maths AA - Option/AHL: Maclaurin series).\n\nIdea: a Taylor polynomial is the \"best possible\" polynomial copy of a function\nnear one point. Adding terms widens the region where the copy is good.\n\nRun:  python taylor_series.py\n\"\"\"\n\nimport math\n\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.animation import FuncAnimation\n\n# --- the function we approximate, and its Maclaurin coefficients -------------\n# sin(x) = x - x^3/3! + x^5/5! - ...\nCENTRE = 0.0\nMAX_TERMS = 10\n\n\ndef taylor_sin(x, n_terms):\n    \"\"\"Maclaurin polynomial of sin(x) using n_terms non-zero terms.\"\"\"\n    total = np.zeros_like(x)\n    for k in range(n_terms):\n        power = 2 * k + 1\n        total = total + ((-1) ** k) * x**power / math.factorial(power)\n    return total\n\n\ndef main():\n    x = np.linspace(-4 * np.pi, 4 * np.pi, 800)\n    exact = np.sin(x)\n\n    fig, ax = plt.subplots(figsize=(9, 5))\n    ax.plot(x, exact, color=\"black\", lw=2, label=\"sin(x)\")\n    approx_line, = ax.plot([], [], color=\"crimson\", lw=2, label=\"Taylor polynomial\")\n    ax.axvline(CENTRE, color=\"grey\", ls=\":\", lw=1)\n\n    ax.set_ylim(-3, 3)\n    ax.set_xlim(x[0], x[-1])\n    ax.set_xlabel(\"x\")\n    ax.set_ylabel(\"y\")\n    ax.legend(loc=\"upper right\")\n    ax.grid(alpha=0.3)\n    title = ax.set_title(\"\")\n\n    def frame(i):\n        n = i + 1\n        approx_line.set_data(x, taylor_sin(x, n))\n        highest = 2 * n - 1\n        title.set_text(f\"{n} term(s) - polynomial up to x^{highest}\")\n        return approx_line, title\n\n    anim = FuncAnimation(fig, frame, frames=MAX_TERMS, interval=900, blit=False)\n    plt.tight_layout()\n    plt.show()\n    return anim\n\n\nif __name__ == \"__main__\":\n    main()\n",
